import { readFile } from 'node:fs/promises';
import { handleProductPageRequest } from '../server/seo/productPage.js';

// Artifacts generated by the build and included by vercel.json.
let cachedShell = null;

async function readShell() {
  if (cachedShell === null) {
    cachedShell = await readFile(new URL('../dist/server/shell.html', import.meta.url), 'utf8');
  }
  return cachedShell;
}

async function renderPage(result, slug) {
  const { renderProductPage } = await import('../dist/server/entry-product-server.js');
  return renderProductPage(result, slug);
}

export default function handler(request, response) {
  return handleProductPageRequest(request, response, { readShell, renderPage });
}
